namespace CSharpPracticum.Tasks.Level2;
internal class Employee(string name,int age,decimal salary,string department){public string Name{get;}=name;public int Age{get;}=age;public decimal Salary{get;}=salary;public string Department{get;}=department;}
internal class Task33_Employees:ITask{public string Title=>"Задание 33: LINQ — сотрудники";public string Description=>"Найти топ зарплат, среднее по отделам и сотрудников старше 30.";public string[] Requirements=>new[]{"Employee с Name, Age, Salary, Department.","Список из 10+ сотрудников.","LINQ: top-3, GroupBy+Average, Where Age > 30."};public void Run(){Employee[] e={new("Анна",25,90000,"IT"),new("Борис",34,80000,"IT"),new("Вера",41,70000,"Продажи"),new("Глеб",29,60000,"Продажи"),new("Дина",37,95000,"IT"),new("Егор",32,65000,"Поддержка"),new("Жанна",45,88000,"Продажи"),new("Илья",28,55000,"Поддержка"),new("Кира",39,72000,"IT"),new("Лев",31,61000,"Поддержка")};Console.WriteLine("Топ-3:");foreach(var x in e.OrderByDescending(x=>x.Salary).Take(3))Console.WriteLine($"{x.Name}: {x.Salary}");Console.WriteLine("Средняя зарплата:");foreach(var g in e.GroupBy(x=>x.Department))Console.WriteLine($"{g.Key}: {g.Average(x=>x.Salary):F2}");Console.WriteLine("Старше 30:");foreach(var x in e.Where(x=>x.Age>30))Console.WriteLine(x.Name);}}
